<?php

namespace Ediligence\EdiligenceBundle\Repository;
Use Doctrine\ORM\Query\Expr\Join;
/**
 * TinstructionRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class TimputInstructionRepository extends \Doctrine\ORM\EntityRepository
{
   public function findinstruct($imputation) {
      $qb = $this->createQueryBuilder('int')
                 ->select("int, (case when sc.code_sc Is Not Null then sc.abrv else case when sd.code_sd Is Not Null then sd.abrv else case when dc.code_dc Is Not Null then dc.sigle else case when dg.codeDg Is Not Null then dg.abrv else case when a.matricule Is Not Null Then Concat(a.nom, ' ', a.prenoms, ' ', a.nomJeuneFille) else 1 end  end end end end) as service,"
                         . "i.libIbstruction")
                 ->leftJoin('AgentBundle:DirectionGenerale', 'dg',  Join::WITH,'int.idImputDir = dg.codeDg')
                 ->leftJoin('AgentBundle:Direction', 'dc',  Join::WITH,'int.idImputDir = dc.code_dc')
                 ->leftJoin('AgentBundle:SousDirection', 'sd',  Join::WITH,'int.idImputDir = sd.code_sd')
                 ->leftJoin('AgentBundle:ServiceDirection', 'sc',  Join::WITH,'int.idImputDir = sc.code_sc')
                 ->leftJoin('AgentBundle:Agent', 'a',  Join::WITH,'int.idImputDir = a.matricule')
                 ->innerJoin('EdiligenceBundle:Tinstruction', 'i',  Join::WITH,'int.instImput = i.id')
                 ->groupBy('int.idImputDir, service, i.id')
                 ->where('int.imputation = :imputation')
                 ->setParameter("imputation", $imputation);
                 
      
      return $qb->getQuery()->getResult(); 
   } 
   
  public function find_inst($imputation,$service, $mat){
    $qb = $this->createQueryBuilder('int')
               ->where("int.imputation =:imputation")
               ->andWhere("(int.idImputDir ='".$service."' Or int.idImputDir ='".$mat."')")
               ->setParameter("imputation", $imputation);
    
    return $qb->getQuery()->getResult();
  }
   
}
